DROP TABLE IF EXISTS `contract`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `contract` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `create_time` datetime(6) NOT NULL,
  `update_time` datetime(6) NOT NULL,
  `date` date NOT NULL,
  `contract_number` varchar(20) NOT NULL,
  `customer_id` bigint NOT NULL,
  `quantity` int NOT NULL,
  `total_price` decimal(10,2) NOT NULL,
  `order_number` int NOT NULL,
  `invoice_completed` tinyint(1) NOT NULL,
  `payment_completed` tinyint(1) NOT NULL,
  `is_delete` tinyint(1) NOT NULL,
  `attachment` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `contract_number` (`contract_number`),
  KEY `cono_contract_customer_id_d83a2ad9_fk_cono_customer_id` (`customer_id`),
  CONSTRAINT `cono_contract_customer_id_d83a2ad9_fk_cono_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=100457 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
