DROP TABLE IF EXISTS `product_delivery`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_delivery` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `create_time` datetime(6) NOT NULL,
  `update_time` datetime(6) NOT NULL,
  `date` date NOT NULL,
  `quantity` int DEFAULT NULL,
  `contract_id` bigint NOT NULL,
  `delivery_man_id` bigint NOT NULL,
  `is_delete` tinyint(1) NOT NULL,
  `product` varchar(32) DEFAULT NULL,
  `productcategory` varchar(32) DEFAULT NULL,
  `customer_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `product_delivery_contract_id_bf4f046d_fk_contract_id` (`contract_id`),
  KEY `product_delivery_delivery_man_id_a572ef68_fk_user_id` (`delivery_man_id`),
  KEY `product_delivery_customer_id_8bbbb364_fk_customer_id` (`customer_id`),
  CONSTRAINT `product_delivery_customer_id_8bbbb364_fk_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`),
  CONSTRAINT `product_delivery_delivery_man_id_a572ef68_fk_user_id` FOREIGN KEY (`delivery_man_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=180 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

